    'tut.warehouses-add-manager.title': 'Manager Details',
    'tut.warehouses-add-manager.desc': 'Assign a manager to the warehouse. Include their name, phone number, and email for contact purposes.',
    'tut.warehouses-add-manager.instruction': 'Enter the manager\\\'s name (e.g. "Abebe Kebede"), phone number with area code, and email address. This helps with coordination.',
    'tut.warehouses-add-submit.title': 'Saving the Warehouse',
    'tut.warehouses-add-submit.desc': 'Review the details and click "Create Warehouse" to save the new location.',
    'tut.warehouses-add-submit.instruction': 'Click "Create Warehouse" to save. The warehouse will appear in the list and be available for stock transfers.',
    'tut.warehouses-transfer-open.title': 'Transferring Stock Between Warehouses',
    'tut.warehouses-transfer-open.desc': 'Move inventory from one warehouse to another. Select source, destination, item, and quantity.',
    'tut.warehouses-transfer-open.instruction': 'Click the "Transfer Stock" button to open the form.',
    'tut.warehouses-transfer-source.title': 'Select Source & Destination',
    'tut.warehouses-transfer-source.desc': 'Choose which warehouse the stock is leaving and which one it\\\'s going to. They must be different.',
