    'tut.orders-create-submit.title': 'Creating the Order',
    'tut.orders-create-submit.desc': 'Review the cart total and click "Create Order" to save. The order will appear with "Pending" status.',
    'tut.orders-create-submit.instruction': 'Verify the items and total. Click "Create Order" to finalize. You can convert it to a sale or debt later.',
    'tut.orders-convert-sale.title': 'Converting an Order to Sale',
    'tut.orders-convert-sale.desc': 'When the customer is ready, convert the order to a sale. Select the payment method to complete the transaction.',
