    'tut.employees-account-credentials.desc': 'Set the login username and a numeric PIN. The PIN is used for quick access. Optionally force a password change on next login.',
    'tut.employees-account-credentials.instruction': 'Enter a unique username (e.g. johndoe). Set a 4-digit PIN (e.g. 1234). Check "Force password change" if this is a first-time user.',
    'tut.employees-account-submit.title': 'Creating the Account',
    'tut.employees-account-submit.desc': 'Click "Create Account" to finalize. The employee can now log in with their credentials.',
    'tut.employees-account-submit.instruction': 'Click "Create Account" to save. Share the credentials with the employee securely.',
    'tut.employees-best-practices.title': 'Employee Best Practices',
    'tut.employees-best-practices.desc': 'Keep your team organized.',
    'tut.employees-best-practices.instruction': '• Update employee records when roles change\n• Use strong PINs for all accounts\n• Review permissions quarterly\n• Remove accounts when employees leave\n• Keep emergency contact info current',
    'tut.tutorial-shipments.title': 'Shipment Tracking',
